mirror_fetch() {
    # mirror_fetch <key> <dest>: download a bundled file, and refuse it unless its sha256 matches the pinned value
    local key="$1" dest="$2" want got
    want="${MIRROR_SHA256[$key]:-}"
    if [ -z "$want" ]; then
        echo "No pinned sha256 for $key in this installer" >&2
        return 1
    fi
    if ! command curl -fsSL --retry 3 -o "$dest" "$REBECCA_MIRROR_BASE/$key"; then
        echo "Could not download $key from $REBECCA_MIRROR_BASE" >&2
        rm -f "$dest"
        return 1
    fi
    got=$(sha256sum "$dest" | awk '{print $1}')
    if [ "$got" != "$want" ]; then
        echo "sha256 mismatch for $key: expected $want, got $got" >&2
        rm -f "$dest"
        return 1
    fi
}

mirror_local_ip() {
    # Replaces the public-IP lookup (ifconfig.io). Uses the server's own address; NODE_IP overrides it.
    # hostname -I is used because iproute2 is not installed until the bundle packages are.
    if [ "$1" = "4" ]; then
        hostname -I 2>/dev/null | tr ' ' '\n' | grep -v ':' | grep . | head -n 1
    else
        hostname -I 2>/dev/null | tr ' ' '\n' | grep ':' | head -n 1
    fi
}

mirror_unsupported() {
    echo "$1 needs the internet and is not part of this offline bundle" >&2
    exit 1
}

mirror_xray_key() {
    # Xray publishes one zip per architecture; the bundle has the one that matches this machine
    case "$(uname -m)" in
        x86_64|amd64) echo "xray/Xray-linux-64.zip" ;;
        aarch64|arm64) echo "xray/Xray-linux-arm64-v8a.zip" ;;
        *)
            echo "Architecture $(uname -m) is not part of this offline bundle" >&2
            return 1
            ;;
    esac
}

mirror_apt_profile_install() {
    # mirror_apt_profile_install <base|mysql|mariadb|sqlite>: installs one bundled package set for this
    # Ubuntu release and architecture. Each .deb is verified before dpkg sees it. sqlite needs no packages.
    local profile="$1" rel arch key file dir
    local debs=()
    if [ -z "$profile" ] || [ "$profile" = "sqlite" ]; then
        return 0
    fi
    rel=$( . /etc/os-release && echo "$VERSION_ID")
    case "$rel" in
        22.04|24.04|26.04) ;;
        *)
            echo "Ubuntu $rel is not covered by this offline bundle" >&2
            exit 1
            ;;
    esac
    arch=$(dpkg --print-architecture)
    dir=$(mktemp -d)
    for key in "${!MIRROR_SHA256[@]}"; do
        case "$key" in
            "apt/$rel/$arch/$profile/"*)
                file="$dir/$(basename "$key")"
                if ! mirror_fetch "$key" "$file"; then
                    rm -rf "$dir"
                    exit 1
                fi
                debs+=("$file")
                ;;
        esac
    done
    if [ "${#debs[@]}" -eq 0 ]; then
        echo "The bundle has no $profile packages for Ubuntu $rel $arch" >&2
        rm -rf "$dir"
        exit 1
    fi
    # dpkg takes the whole set at once, so the bundle's packages satisfy each other without apt
    # looking for anything elsewhere. Each set is the full dependency closure for its release.
    # dpkg checks pre-dependencies in the order it unpacks, so a package can fail on one pass and
    # install on the next once its pre-dependency is configured. Repeat passes until the set is done.
    local pass
    for pass in 1 2 3 4 5 6; do
        if DEBIAN_FRONTEND=noninteractive dpkg -i --force-confold "${debs[@]}" >/dev/null 2>&1; then
            break
        fi
    done
    if ! DEBIAN_FRONTEND=noninteractive dpkg -i --force-confold "${debs[@]}" >/dev/null 2>&1; then
        DEBIAN_FRONTEND=noninteractive dpkg -i --force-confold "${debs[@]}" || true
        echo "Installing the bundled $profile packages failed" >&2
        rm -rf "$dir"
        exit 1
    fi
    rm -rf "$dir"
}

mirror_apt_bundle_install() {
    mirror_apt_profile_install base
}
# ---- end offline mirror ----

