prompt_branch_selection() {
    local question
    if [[ "$BRANCH" == "dev" ]]; then
        question="Keep using the dev branch? (Y/n): "
    else
        question="Do you want to install Rebecca-node using the dev branch? (y/N): "
    fi
    read -p "$question" -r branch_answer
    if [[ "$BRANCH" == "dev" ]]; then
        if [[ -z "$branch_answer" || "$branch_answer" =~ ^[Yy]$ ]]; then
            set_branch_variables dev
        else
            set_branch_variables master
        fi
    else
        if [[ "$branch_answer" =~ ^[Yy]$ ]]; then
            set_branch_variables dev
        else
            set_branch_variables master
        fi
    fi
    colorized_echo blue "Selected branch: $BRANCH (image tag: $IMAGE_TAG)"
}

normalize_install_mode() {
    local mode
    mode=$(printf '%s' "${1:-}" | tr '[:upper:]' '[:lower:]')
    case "$mode" in
        docker|dockerized|compose)
            echo "docker"
        ;;
        binary|bin|native)
            echo "binary"
        ;;
        "")
            echo ""
        ;;
        *)
            colorized_echo red "Invalid install mode: $1" >&2
            colorized_echo yellow "Valid modes are: docker, binary" >&2
            exit 1
        ;;
    esac
}

script_install_mode() {
    case "${REBECCA_NODE_SCRIPT_FLAVOR:-docker}" in
        docker|dockerized|compose)
            echo "docker"
        ;;
        binary|bin|native)
            echo "binary"
        ;;
        mixed|"")
            echo ""
        ;;
        *)
            colorized_echo red "Invalid node script flavor: $REBECCA_NODE_SCRIPT_FLAVOR" >&2
            exit 1
        ;;
    esac
}

get_install_mode() {
    if [ -f "$INSTALL_MODE_FILE" ]; then
        normalize_install_mode "$(tr -d '[:space:]' < "$INSTALL_MODE_FILE")"
        return
    fi
    if [ -x "$BINARY_NODE" ] || [ -f "$BINARY_SERVICE_UNIT" ]; then
        echo "binary"
        return
    fi
    if [ -f "$COMPOSE_FILE" ]; then
        echo "docker"
        return
    fi
    local forced_mode
    forced_mode=$(script_install_mode)
    if [ -n "$forced_mode" ]; then
        echo "$forced_mode"
        return
    fi
    echo "docker"
}

is_binary_install() {
    [ "$(get_install_mode)" = "binary" ]
}

select_install_mode() {
    echo "binary"
}

prompt_node_name() {
    if [ "$APP_NAME_FROM_ARG" -eq 1 ] || [ ! -t 0 ]; then
        return
    fi

    local default_name="${APP_NAME:-$SCRIPT_DEFAULT_APP_NAME}"
    local node_name
    while true; do
        read -r -p "Node name [$default_name]: " node_name
        node_name="${node_name:-$default_name}"
        if [[ "$node_name" =~ ^[a-zA-Z0-9][a-zA-Z0-9_-]*$ ]]; then
            APP_NAME="$node_name"
            APP_DIR=""
            set_app_context
            return
        fi
        colorized_echo red "Invalid node name. Use letters, numbers, hyphens, or underscores."
    done
}

ensure_script_matches_installed_mode() {
    local forced_mode
    local installed_mode
    forced_mode=$(script_install_mode)
    if [ -z "$forced_mode" ] || [ ! -d "$APP_DIR" ]; then
        return
    fi
    installed_mode=$(get_install_mode)
    if [ "$installed_mode" != "$forced_mode" ]; then
        colorized_echo red "This Rebecca-node installation is in ${installed_mode} mode, but ${0##*/} is the ${forced_mode} script."
        if [ "$installed_mode" = "binary" ]; then
            colorized_echo yellow "Use the Rebecca-node binary script."
        else
            colorized_echo yellow "Use the Rebecca-node Docker script."
        fi
        exit 1
    fi
}

